from pagina import B

def N(icono, t1, t2=None, sub=None, uso=False):
    return {'tipo': 'nodo', 'icono': icono, 't1': t1, 't2': t2, 'sub': sub, 'uso': uso}

def R(l1, l2, no=None, ciclo=None, textoCiclo=None):
    return {'tipo': 'rombo', 'l1': l1, 'l2': l2, 'no': no, 'ciclo': ciclo, 'textoCiclo': textoCiclo}

